package com.rahul.cashbook;

import android.app.*;
import android.os.Bundle;
import android.content.*;
import android.database.*;
import android.database.sqlite.*;
import android.graphics.Typeface;
import android.net.Uri;
import android.view.*;
import android.widget.*;
import java.text.SimpleDateFormat;
import java.util.*;

public class MainActivity extends Activity {
  DB db; LinearLayout root, body; String currency="AED"; Spinner categorySpinner,payerSpinner; EditText amountInput,remarksInput; TextView totalView;
  final int BLUE=0xff2563eb, DARK=0xff102a43, GREEN=0xff15803d;
  @Override public void onCreate(Bundle b){super.onCreate(b); db=new DB(this); showHome();}
  TextView text(String s,int size,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(0xff172b4d);if(bold)t.setTypeface(null,Typeface.BOLD);t.setPadding(4,8,4,8);return t;}
  Button button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setOnClickListener(v->r.run());return b;}
  void base(String title){root=new LinearLayout(this);root.setOrientation(1);root.setPadding(18,12,18,12);root.setBackgroundColor(0xfff5f7fb);setContentView(root); TextView h=text("CashBook By RaaHul  ·  "+title,23,true);h.setTextColor(DARK);root.addView(h); ScrollView sc=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);body.setPadding(0,8,0,20);sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1)); LinearLayout nav=new LinearLayout(this);nav.setOrientation(0);nav.addView(button("Home",this::showHome),new LinearLayout.LayoutParams(0,-2,1));nav.addView(button("Add",this::showAdd),new LinearLayout.LayoutParams(0,-2,1));nav.addView(button("Reports",this::showReports),new LinearLayout.LayoutParams(0,-2,1));nav.addView(button("Manage",this::showManage),new LinearLayout.LayoutParams(0,-2,1));root.addView(nav);}
  void line(String s){body.addView(text(s,16,false));}
  void showHome(){base("Overview"); double m=db.total("",""); double r=db.total("Rahul",""); double su=db.total("Suchithra",""); line("TOTAL SPENDING"); TextView total=text(currency+" "+fmt(m),30,true);total.setTextColor(BLUE);body.addView(total);line("Rahul paid:  "+currency+" "+fmt(r));line("Suchithra paid:  "+currency+" "+fmt(su));line("Combined spending:  "+currency+" "+fmt(m));body.addView(button("＋  Add expense",this::showAdd));line("RECENT EXPENSES");Cursor c=db.getReadableDatabase().rawQuery("SELECT date,category,payer,amount,remarks FROM expenses ORDER BY id DESC LIMIT 12",null);while(c.moveToNext())line(c.getString(0)+"  ·  "+c.getString(1)+"  ·  "+c.getString(2)+"  ·  "+currency+" "+fmt(c.getDouble(3))+ (c.getString(4).isEmpty()?"":"\n   "+c.getString(4)));c.close();}
  String[] active(String table){ArrayList<String>a=new ArrayList<>();Cursor c=db.getReadableDatabase().rawQuery("SELECT name FROM "+table+" WHERE active=1 ORDER BY name",null);while(c.moveToNext())a.add(c.getString(0));c.close();return a.toArray(new String[0]);}
  EditText edit(String hint){EditText e=new EditText(this);e.setSingleLine(true);e.setHint(hint);body.addView(e);return e;}
  Spinner spinner(String[] vals){Spinner s=new Spinner(this);ArrayAdapter<String>a=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,vals);s.setAdapter(a);body.addView(s);return s;}
  void showAdd(){base("Add expense");line("Amount ("+currency+")");amountInput=edit("0.00");line("Date");TextView date=text(new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date()),17,true);body.addView(date);date.setOnClickListener(v->{Calendar cal=Calendar.getInstance();new DatePickerDialog(this,(p,y,m,d)->date.setText(String.format(Locale.US,"%04d-%02d-%02d",y,m+1,d)),cal.get(Calendar.YEAR),cal.get(Calendar.MONTH),cal.get(Calendar.DAY_OF_MONTH)).show();});line("Category");categorySpinner=spinner(active("categories"));line("Paid by");payerSpinner=spinner(active("payers"));line("Remarks");remarksInput=edit("e.g. Dinner, groceries, taxi");body.addView(button("SAVE EXPENSE",()->{try{double amount=Double.parseDouble(amountInput.getText().toString().trim());if(amount<=0)throw new Exception();String[] cats=active("categories"),payers=active("payers");if(cats.length==0||payers.length==0)throw new Exception();ContentValues v=new ContentValues();v.put("date",date.getText().toString());v.put("amount",amount);v.put("category",cats[categorySpinner.getSelectedItemPosition()]);v.put("payer",payers[payerSpinner.getSelectedItemPosition()]);v.put("remarks",remarksInput.getText().toString());db.getWritableDatabase().insert("expenses",null,v);Toast.makeText(this,"Expense saved",Toast.LENGTH_SHORT).show();showHome();}catch(Exception ex){Toast.makeText(this,"Enter a valid amount and create at least one category and payer",Toast.LENGTH_LONG).show();}}));}
  void showManage(){base("Manage");line("EXPENSE CATEGORIES");EditText cat=new EditText(this);cat.setHint("New category name");body.addView(cat);body.addView(button("＋ Add category",()->{String n=cat.getText().toString().trim();if(!n.isEmpty()){db.addName("categories",n);showManage();}}));listNames("categories");line("PAYERS");EditText payer=new EditText(this);payer.setHint("New payer name");body.addView(payer);body.addView(button("＋ Add payer",()->{String n=payer.getText().toString().trim();if(!n.isEmpty()){db.addName("payers",n);showManage();}}));listNames("payers");line("CURRENCY");EditText cur=new EditText(this);cur.setSingleLine(true);cur.setText(currency);body.addView(cur);body.addView(button("Save currency",()->{currency=cur.getText().toString().trim().toUpperCase(Locale.US);if(currency.isEmpty())currency="AED";Toast.makeText(this,"Currency updated",0).show();}));}
  void listNames(String table){Cursor c=db.getReadableDatabase().rawQuery("SELECT id,name,active FROM "+table+" ORDER BY name",null);while(c.moveToNext()){int id=c.getInt(0);String n=c.getString(1);boolean active=c.getInt(2)==1;LinearLayout row=new LinearLayout(this);row.setOrientation(0);TextView label=text(n+(active?"":" (inactive)"),15,true);row.addView(label,new LinearLayout.LayoutParams(0,-2,1));row.addView(button(active?"Deactivate":"Activate",()->{db.getWritableDatabase().execSQL("UPDATE "+table+" SET active=? WHERE id=?",new Object[]{active?0:1,id});showManage();}));row.addView(button("Rename",()->{EditText e=new EditText(this);e.setText(n);new AlertDialog.Builder(this).setTitle("Rename").setView(e).setPositiveButton("Save",(d,w)->{db.getWritableDatabase().execSQL("UPDATE "+table+" SET name=? WHERE id=?",new Object[]{e.getText().toString().trim(),id});showManage();}).setNegativeButton("Cancel",null).show();}));row.addView(button("Delete",()->new AlertDialog.Builder(this).setMessage("Delete this item? Existing expense records will keep the original name.").setPositiveButton("Delete",(d,w)->{db.getWritableDatabase().execSQL("DELETE FROM "+table+" WHERE id=?",new Object[]{id});showManage();}).setNegativeButton("Cancel",null).show()));body.addView(row);}c.close();}
  void showReports(){base("Reports");line("Choose report period");body.addView(button("Daily report",()->report("date",new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date()))));body.addView(button("This month",()->report("month",new SimpleDateFormat("yyyy-MM",Locale.US).format(new Date()))));body.addView(button("All-time payer summary",()->payerReport()));body.addView(button("Category-wise summary",()->groupReport("category")));body.addView(button("Export all transactions (CSV)",()->exportCsv()));}
  void report(String kind,String value){base(kind.equals("date")?"Daily report":"Monthly report");String where=kind.equals("date")?"date=?":"substr(date,1,7)=?";Cursor c=db.getReadableDatabase().rawQuery("SELECT payer, SUM(amount), COUNT(*) FROM expenses WHERE "+where+" GROUP BY payer",new String[]{value});double sum=0;while(c.moveToNext()){line(c.getString(0)+"  ·  "+currency+" "+fmt(c.getDouble(1))+"  ·  "+c.getInt(2)+" transactions");sum+=c.getDouble(1);}c.close();line("TOTAL: "+currency+" "+fmt(sum));body.addView(button("Export CSV",this::exportCsv));}
  void payerReport(){base("Payer summary");Cursor c=db.getReadableDatabase().rawQuery("SELECT payer,SUM(amount),COUNT(*) FROM expenses GROUP BY payer ORDER BY SUM(amount) DESC",null);double total=0;while(c.moveToNext()){line(c.getString(0)+"  ·  "+currency+" "+fmt(c.getDouble(1))+"  ·  "+c.getInt(2)+" transactions");total+=c.getDouble(1);}c.close();line("COMBINED TOTAL: "+currency+" "+fmt(total));}
  void groupReport(String field){base("Category summary");Cursor c=db.getReadableDatabase().rawQuery("SELECT category,SUM(amount),COUNT(*) FROM expenses GROUP BY category ORDER BY SUM(amount) DESC",null);while(c.moveToNext())line(c.getString(0)+"  ·  "+currency+" "+fmt(c.getDouble(1))+"  ·  "+c.getInt(2)+" transactions");c.close();}
  void exportCsv(){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("text/csv");i.putExtra(Intent.EXTRA_TITLE,"cashbook-expenses.csv");startActivityForResult(i,7);}
  @Override protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(r==7&&result==RESULT_OK&&data!=null){try(java.io.OutputStream o=getContentResolver().openOutputStream(data.getData());java.io.OutputStreamWriter w=new java.io.OutputStreamWriter(o)){w.write("Date,Amount,Currency,Category,Paid By,Remarks\n");Cursor c=db.getReadableDatabase().rawQuery("SELECT date,amount,category,payer,remarks FROM expenses ORDER BY date",null);while(c.moveToNext()){w.write(csv(c.getString(0))+","+c.getDouble(1)+","+currency+","+csv(c.getString(2))+","+csv(c.getString(3))+","+csv(c.getString(4))+"\n");}c.close();w.flush();Toast.makeText(this,"CSV exported",0).show();}catch(Exception e){Toast.makeText(this,"Export failed: "+e.getMessage(),1).show();}}}
  String csv(String s){return "\""+(s==null?"":s.replace("\"","\"\""))+"\"";} String fmt(double d){return String.format(Locale.US,"%,.2f",d);}
  static class DB extends SQLiteOpenHelper {DB(Context c){super(c,"cashbook.db",null,1);}public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE expenses(id INTEGER PRIMARY KEY AUTOINCREMENT,date TEXT,amount REAL,category TEXT,payer TEXT,remarks TEXT)");d.execSQL("CREATE TABLE categories(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT UNIQUE,active INTEGER DEFAULT 1)");d.execSQL("CREATE TABLE payers(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT UNIQUE,active INTEGER DEFAULT 1)");d.execSQL("INSERT INTO categories(name) VALUES('Food'),('Groceries'),('Health'),('Transportation'),('Entertainment')");d.execSQL("INSERT INTO payers(name) VALUES('Rahul'),('Suchithra')");}public void onUpgrade(SQLiteDatabase d,int o,int n){}void addName(String t,String n){try{ContentValues v=new ContentValues();v.put("name",n);getWritableDatabase().insertOrThrow(t,null,v);}catch(Exception ignored){}}double total(String payer,String date){String q="SELECT COALESCE(SUM(amount),0) FROM expenses WHERE 1=1";ArrayList<String>a=new ArrayList<>();if(!payer.isEmpty()){q+=" AND payer=?";a.add(payer);}if(!date.isEmpty()){q+=" AND date LIKE ?";a.add(date+"%");}Cursor c=getReadableDatabase().rawQuery(q,a.toArray(new String[0]));double x=0;if(c.moveToFirst())x=c.getDouble(0);c.close();return x;}}
}
